"""Command-line interface: ``pennywise balance|summary|list|add|export``."""

import argparse
import csv
import io
import json
import re
import sys
from datetime import date
from decimal import Decimal, localcontext

from . import ledger
from .ledger import ParseError

_CENTS = Decimal("0.01")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


class _ReadError(Exception):
    """The ledger could not be read (exit 2)."""


def _fmt_amount(amount):
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, len(amount.as_tuple().digits) + 4)
        value = amount.quantize(_CENTS)
    if value == 0:
        value = Decimal("0.00")
    return format(value, "f")


def _format_entry(entry):
    parts = [entry.date.isoformat(), entry.category, _fmt_amount(entry.amount)]
    if entry.note:
        parts.append(entry.note)
    return " ".join(parts)


def _date_arg(text):
    try:
        if not _DATE_RE.fullmatch(text):
            raise ValueError(text)
        return date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        raise argparse.ArgumentTypeError(
            "invalid date %r (expected YYYY-MM-DD)" % text
        ) from None


def _read_ledger(path):
    try:
        if path == "-":
            stream = sys.stdin
            raw = getattr(stream, "buffer", None)
            data = raw.read() if raw is not None else stream.read()
        else:
            with open(path, "rb") as handle:
                data = handle.read()
        text = data.decode("utf-8-sig") if isinstance(data, bytes) else data
    except (OSError, UnicodeDecodeError) as exc:
        name = "standard input" if path == "-" else path
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise _ReadError("cannot read %s: %s" % (name, reason)) from None
    return ledger.parse(text)


def _chronological(entries):
    return sorted(entries, key=lambda e: e.date)  # stable: same-day keeps file order


def _selected(args):
    entries = _read_ledger(args.file)
    entries = ledger.filter_entries(
        entries, category=args.category, since=args.since, until=args.until
    )
    return _chronological(entries)


def _cmd_balance(args):
    total = _fmt_amount(ledger.balance(_read_ledger(args.file)))
    return json.dumps({"balance": total}) if args.json else total


def _cmd_summary(args):
    entries = _read_ledger(args.file)
    totals = ledger.by_month(entries) if args.by == "month" else ledger.by_category(entries)
    totals = {name: _fmt_amount(total) for name, total in totals.items()}
    if args.json:
        return json.dumps(totals, sort_keys=True)
    return "\n".join("%s  %s" % item for item in sorted(totals.items()))


def _cmd_list(args):
    entries = _selected(args)
    if args.json:
        return json.dumps(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": _fmt_amount(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return "\n".join(_format_entry(e) for e in entries)


def _cmd_export(args):
    entries = _selected(args)
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, _fmt_amount(e.amount), e.note])
    return buffer.getvalue().rstrip("\n")


def _cmd_add(args):
    category = args.category
    note = args.note
    if not category.strip():
        raise ParseError("category must not be empty", 1)
    candidate = " ".join([args.date, category, args.amount] + ([note] if note else []))
    if len(candidate.splitlines()) != 1:
        raise ParseError("entry must be a single line (no newlines)", 1)
    entries = ledger.parse(candidate)
    if (
        len(entries) != 1
        or entries[0].category != category.lower()
        or entries[0].note != note.strip()
        or entries[0].date.isoformat() != args.date
    ):
        raise ParseError(
            "invalid entry: category must be one word and the amount a plain number", 1
        )
    line = _format_entry(entries[0])
    try:
        prefix = b""
        try:
            with open(args.file, "rb") as handle:
                handle.seek(0, 2)
                if handle.tell() > 0:
                    handle.seek(-1, 2)
                    if handle.read(1) not in (b"\n", b"\r"):
                        prefix = b"\n"
        except FileNotFoundError:
            pass
        with open(args.file, "ab") as handle:
            handle.write(prefix + line.encode("utf-8") + b"\n")
    except OSError as exc:
        raise _ReadError("cannot write %s: %s" % (args.file, exc.strerror or exc)) from None
    return line


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell where the household money went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def reader(name, help_text):
        p = sub.add_parser(name, help=help_text, description=help_text)
        p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
        return p

    def with_json(p):
        p.add_argument("--json", action="store_true", help="print JSON")

    def with_filters(p):
        p.add_argument("--category", help="only this category (any case)")
        p.add_argument("--since", type=_date_arg, metavar="DATE", help="from DATE (YYYY-MM-DD), inclusive")
        p.add_argument("--until", type=_date_arg, metavar="DATE", help="up to DATE (YYYY-MM-DD), inclusive")

    p = reader("balance", "print the total of all amounts")
    with_json(p)
    p.set_defaults(func=_cmd_balance)

    p = reader("summary", "print totals per category or month")
    p.add_argument("--by", choices=["category", "month"], default="category")
    with_json(p)
    p.set_defaults(func=_cmd_summary)

    p = reader("list", "print entries, oldest first")
    with_filters(p)
    with_json(p)
    p.set_defaults(func=_cmd_list)

    p = reader("export", "print entries as CSV")
    p.add_argument("--format", choices=["csv"], default="csv")
    with_filters(p)
    p.set_defaults(func=_cmd_export)

    p = sub.add_parser("add", help="append an entry to a ledger file", description="append an entry to a ledger file")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")
    p.set_defaults(func=_cmd_add)
    return parser


def main(argv=None):
    """Run the CLI; returns the exit status (0 ok, 1 ledger/entry mistake, 2 usage/IO)."""
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = args.func(args)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _ReadError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    sys.stdout.write(output + "\n" if output else "")
    return 0


if __name__ == "__main__":
    sys.exit(main())
