import unittest
from datetime import date
from decimal import Decimal

import pennywise
from pennywise import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    parse,
)

SAMPLE = """# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


class ParseTests(unittest.TestCase):
    def test_sample_ledger(self):
        entries = parse(SAMPLE)
        self.assertEqual(
            entries,
            [
                Entry(date(2024, 3, 1), "salary", Decimal("2500.00"), "March pay"),
                Entry(date(2024, 3, 2), "groceries", Decimal("-42.50"), "weekly shop"),
                Entry(date(2024, 3, 5), "rent", Decimal("-900"), ""),
            ],
        )
        self.assertIsInstance(entries[0].date, date)
        self.assertIsInstance(entries[0].amount, Decimal)

    def test_package_exports(self):
        for name in ("Entry", "ParseError", "parse", "balance", "by_category",
                     "by_month", "filter_entries"):
            self.assertTrue(hasattr(pennywise, name), name)

    def test_empty_text(self):
        self.assertEqual(parse(""), [])
        self.assertEqual(parse("\n   \n# only comment\n"), [])

    def test_entry_is_frozen(self):
