    def test_note_may_contain_hash(self):
        (entry,) = parse("2024-03-01 a 1 buy # not a comment")
        self.assertEqual(entry.note, "buy # not a comment")

    def test_valid_amounts(self):
        cases = {
            "12": "12", "12.5": "12.5", "+2500": "2500", "2500.00": "2500.00",
            "-0.99": "-0.99", "-5": "-5", "0": "0", "007": "007",
        }
        for text, expected in cases.items():
            with self.subTest(text):
                (entry,) = parse("2024-01-01 a " + text)
                self.assertEqual(entry.amount, Decimal(expected))
                self.assertEqual(str(entry.amount), str(Decimal(expected)))

    def test_plus_and_bare_amounts_equal(self):
