                with self.assertRaises(ParseError) as ctx:
                    parse("2024-01-01 a " + text)
                self.assertEqual(ctx.exception.line, 1)

    def test_invalid_dates(self):
        for text in ("2024-02-30", "2023-02-29", "2024-13-01", "2024-00-10", "2024-1-01",
                     "24-01-01", "2024/01/01", "20240101", "abc", "2024-01-001"):
            with self.subTest(text):
                with self.assertRaises(ParseError):
                    parse(text + " a 1")

    def test_leap_day_ok(self):
        self.assertEqual(parse("2024-02-29 a 1")[0].date, date(2024, 2, 29))

    def test_too_few_fields(self):
        for text in ("2024-01-01", "2024-01-01 food", "justoneword"):
            with self.subTest(text):
                with self.assertRaises(ParseError):
                    parse(text)

    def test_category_lowercased(self):
        self.assertEqual(parse("2024-01-01 RenT 1")[0].category, "rent")

    def test_line_numbers_count_blank_and_comments(self):
        text = "# c\n\n2024-01-01 a 1\n   \n# another\n2024-01-02 b nope\n"
        with self.assertRaises(ParseError) as ctx:
