        self.assertEqual(result, self.entries)
        self.assertIsNot(result, self.entries)

    def test_category_case_insensitive(self):
        self.assertEqual([e.amount for e in filter_entries(self.entries, category="A")],
                         [Decimal("2"), Decimal("3")])
        self.assertEqual(len(filter_entries(self.entries, category="b")), 2)

    def test_bounds_inclusive(self):
        result = filter_entries(self.entries, since=date(2024, 3, 5), until=date(2024, 3, 10))
        self.assertEqual([e.amount for e in result], [Decimal("1"), Decimal("3")])

    def test_since_only_until_only(self):
        self.assertEqual(len(filter_entries(self.entries, since=date(2024, 3, 6))), 1)
        self.assertEqual(len(filter_entries(self.entries, until=date(2024, 3, 1))), 2)

    def test_order_preserved_not_sorted(self):
        result = filter_entries(self.entries, until=date(2024, 3, 5))
        self.assertEqual([e.date.day for e in result], [5, 1, 1])

    def test_does_not_mutate(self):
        before = list(self.entries)
        filter_entries(self.entries, category="a")
        self.assertEqual(self.entries, before)

    def test_empty_input(self):
        self.assertEqual(filter_entries([], category="a", since=date(2024, 1, 1)), [])


